"use client";

import { BookAppointment } from "@/components/custom/blocks/BookAppointmentBlock";

const DOCTOR = {
  name: "Dr. Priya Nair, MD",
  shortName: "Dr. Nair",
  specialties: "Cardiology and general internal medicine",
  practice: "Riverside Heart & Medical Group",
  photo:
    "https://res.cloudinary.com/dodndg7ai/image/upload/f_webp,q_auto,w_687,c_limit/v1790145142/photo-1638202993928-7267aad84c31-1790145143494.jpg",
  photoAlt: "Portrait of Dr. Priya Nair wearing a lab coat and stethoscope",
  rating: 4.8,
  reviews: 38,
  summary:
    "Reviewers call Dr. Nair careful and approachable. Her heart-care knowledge and plain-spoken answers stand out; some note slow replies to phone messages.",
  location: "Brooklyn, NY, Riverside Heart & Medical Group",
  phone: "(718) 555-0142",
  email: "drnair@example.com",
  languages: "English, Hindi",
};

const SCORES = [
  { label: "Punctuality", value: 4.63 },
  { label: "Warmth and care", value: 4.19 },
  { label: "Explains things well", value: 4.74 },
];

const VISIT_REASONS = [
  { label: "Blood pressure care", value: 35 },
  { label: "Heart health check-ups", value: 25 },
  { label: "Heart failure follow-up", value: 22 },
  { label: "Chest pain workup", value: 18 },
];

const ACTIVITIES = [
  { label: "Clinic", value: 47 },
  { label: "Studies", value: 24 },
  { label: "Mentoring", value: 16 },
  { label: "Paperwork", value: 10 },
  { label: "Other", value: 3 },
];

const SLOT_GROUPS = [
  {
    label: "Morning",
    slots: [{ label: "9:00 AM" }, { label: "10:00 AM" }, { label: "11:00 AM", taken: true }],
  },
  {
    label: "Afternoon",
    slots: [{ label: "12:00 PM" }, { label: "1:00 PM" }, { label: "2:00 PM" }, { label: "3:00 PM", taken: true }],
  },
];

export default function BookAppointmentPage() {
  return (
    <BookAppointment
      variant="solid"
      practitioner={DOCTOR}
      scores={SCORES}
      visitReasons={VISIT_REASONS}
      activities={ACTIVITIES}
      slotGroups={SLOT_GROUPS}
      unavailable={(d) => d.getDay() === 0}
      onBook={async ({ day, slot }) => {
        await fetch("/api/book", { method: "POST", body: JSON.stringify({ day, slot }) });
      }}
      className="min-h-dvh"
    />
  );
}

"use client";

import { BookingCard, type Booking, type BookingSlot } from "@/components/custom/blocks/BookingCardBlock";
import { ChartBlock } from "@/components/custom/blocks/ChartBlock";
import { GlassBackdrop, GlassPanel, type SurfaceVariant } from "@/components/custom/blocks/GlassPanelBlock";
import { HalfStars } from "@/components/custom/blocks/HalfStarsBlock";
import { Languages, Mail, MapPin, Phone } from "lucide-react";
import React from "react";

// ==========================================
// BOOK APPOINTMENT — a practitioner's page that ends in a booking
// ==========================================
// Composed entirely from library pieces: `GlassBackdrop` + `GlassPanel` for
// the surface, `HalfStars` for the scores, `ChartBlock` for the donut and the
// stacked bar, and `BookingCard` for the booking itself.

export interface Practitioner {
  /** Full name as shown in the heading, e.g. "Dr. Priya Nair, MD". */
  name: string;
  /** How the confirmation refers to them, e.g. "Dr. Nair". Falls back to `name`. */
  shortName?: string;
  /** One line under the name, e.g. "Cardiology and general internal medicine". */
  specialties: string;
  practice: string;
  photo: string;
  photoAlt?: string;
  /** Overall score out of 5 — the one loud number on the page. */
  rating: number;
  reviews: number;
  /** A short read of what patients say. */
  summary: string;
  location?: string;
  phone?: string;
  email?: string;
  languages?: string;
}

/** A named score out of 5, e.g. "Punctuality". */
export interface PractitionerScore {
  label: string;
  value: number;
}

/** A labelled share of a whole, in percent. */
export interface Share {
  label: string;
  value: number;
}

/** A group of times, e.g. "Morning". */
export interface SlotGroup {
  label: string;
  slots: BookingSlot[];
}

export interface BookAppointmentProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSubmit"> {
  practitioner: Practitioner;
  /** Named scores shown as stars under the summary. */
  scores?: PractitionerScore[];
  /** Fills the donut. Omit to leave that panel out. */
  visitReasons?: Share[];
  /** Fills the stacked bar. Omit to leave that panel out. */
  activities?: Share[];
  /** Time slots on offer, grouped. */
  slotGroups: SlotGroup[];
  /** Days with nothing free — struck through in the day strip. */
  unavailable?: (day: Date) => boolean;
  /**
   * Called when the person confirms. Return a promise to keep the button busy
   * until the booking is really made; a rejection returns to the form.
   */
  onBook?: (booking: Booking) => void | Promise<void>;
  /** Heading over the booking panel. */
  bookingHeading?: string;
  /** Frosted glass over an aurora, or solid cards with a shadow. */
  variant?: SurfaceVariant;
  /** The three aurora colours behind the glass. Ignored by `solid`. */
  aurora?: [string, string, string];
}

export function BookAppointment({
  practitioner,
  scores = [],
  visitReasons,
  activities,
  slotGroups,
  unavailable,
  onBook,
  bookingHeading = "Schedule a visit",
  variant = "glass",
  aurora = ["#c4b5fd", "#99f6e4", "#fde68a"],
  className,
  ...props
}: BookAppointmentProps) {
  const contact = [
    { Icon: MapPin, value: practitioner.location, href: undefined },
    { Icon: Phone, value: practitioner.phone, href: practitioner.phone ? `tel:${practitioner.phone.replace(/[^\d+]/g, "")}` : undefined },
    { Icon: Mail, value: practitioner.email, href: practitioner.email ? `mailto:${practitioner.email}` : undefined },
    { Icon: Languages, value: practitioner.languages, href: undefined },
  ].filter((row) => row.value);

  return (
    <GlassBackdrop variant={variant} aurora={aurora} className={className} {...props}>
      {/* Portrait and contact */}
      <div className="flex flex-col gap-4 md:col-span-2 lg:col-span-3">
        <GlassPanel shape="slab" className="overflow-hidden">
          <img
            src={practitioner.photo}
            alt={practitioner.photoAlt ?? practitioner.name}
            loading="lazy"
            className="aspect-[3/4] w-full object-cover object-top"
          />
        </GlassPanel>

        {contact.length > 0 && (
          <GlassPanel className="p-5">
            <ul className="space-y-2.5 text-sm">
              {contact.map(({ Icon, value, href }) => (
                <li key={value} className="flex items-center gap-2.5">
                  <Icon className="size-4 shrink-0 text-foreground/50" aria-hidden />
                  {href ? (
                    <a href={href} className="hover:underline">{value}</a>
                  ) : (
                    <span>{value}</span>
                  )}
                </li>
              ))}
            </ul>
          </GlassPanel>
        )}
      </div>

      {/* Name, scores, charts */}
      <div className="flex flex-col gap-4 md:col-span-4 lg:col-span-5">
        <GlassPanel shape="slab" className="flex flex-col gap-5 p-6">
          <div>
            <h1 className="text-2xl font-semibold tracking-tight sm:text-3xl">{practitioner.name}</h1>
            <p className="mt-1 text-sm text-foreground/60">{practitioner.specialties}</p>
          </div>

          <div className="flex gap-4">
            {/* The score is the one loud element on the page */}
            <div className="grid size-24 shrink-0 place-items-center rounded-[30%] bg-primary text-primary-foreground">
              <div className="text-center">
                <p className="text-3xl font-semibold leading-none tabular-nums">{practitioner.rating}</p>
                <p className="mt-1 text-[11px] opacity-80">{practitioner.reviews} reviews</p>
              </div>
            </div>
            <div className="min-w-0">
              <p className="text-xs font-medium text-foreground/50">What patients report</p>
              <p className="mt-1 text-sm leading-relaxed text-foreground/70">{practitioner.summary}</p>
            </div>
          </div>

          {scores.length > 0 && (
            <div className="flex flex-wrap gap-x-6 gap-y-3">
              {scores.map((s) => (
                <div key={s.label} className="shrink-0">
                  <p className="text-xs text-foreground/50">{s.label}</p>
                  <div className="mt-1 flex items-center gap-2">
                    <HalfStars
                      rating={s.value}
                      size={14}
                      showText={false}
                      activeColor="text-amber-500"
                      inactiveColor="text-foreground/20"
                      role="img"
                      aria-label={`${s.label}: ${s.value.toFixed(2)} out of 5`}
                    />
                    <span className="text-sm font-semibold tabular-nums">{s.value.toFixed(2)}</span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </GlassPanel>

        {visitReasons && visitReasons.length > 0 && (
          <GlassPanel className="p-6">
            <h2 className="text-sm font-semibold">Why patients come in</h2>
            <ChartBlock
              type="donut-legend"
              data={visitReasons}
              valueSuffix="%"
              centerLabel="most common"
              hoverLabel="of visits"
              className="mt-4"
            />
          </GlassPanel>
        )}

        {activities && activities.length > 0 && (
          <GlassPanel className="p-6">
            <h2 className="text-sm font-semibold">How her week splits</h2>
            <ChartBlock type="stacked-bar" data={activities} valueSuffix="%" className="mt-4" />
          </GlassPanel>
        )}
      </div>

      {/* Booking */}
      {/* The BookingCard is the panel's whole inside, so its confirmation covers
          the panel edge to edge instead of stopping at the padding. */}
      <GlassPanel shape="slab" className="self-start md:col-span-6 lg:col-span-4">
        <BookingCard className="flex h-full flex-col gap-5 p-6" {...(onBook ? { onBook } : {})}>
          <h2 className="text-lg font-semibold tracking-tight">{bookingHeading}</h2>
          <BookingCard.Days {...(unavailable ? { unavailable } : {})} />
          <div className="space-y-4">
            <p className="text-sm font-semibold">Time</p>
            {slotGroups.map((group) => (
              <BookingCard.Slots key={group.label} label={group.label} slots={group.slots} />
            ))}
          </div>
          <BookingCard.Submit className="mt-auto" />
          <BookingCard.Confirmation
            withName={practitioner.shortName ?? practitioner.name}
            place={practitioner.practice}
          />
        </BookingCard>
      </GlassPanel>
    </GlassBackdrop>
  );
}

export default BookAppointment;

"use client";

import { cn } from "@/lib/utils";
import { ChevronLeft, ChevronRight } from "lucide-react";
import React, {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useState,
  useSyncExternalStore,
} from "react";

// ==========================================
// BOOKING CARD — days, slots, confirm
// ==========================================
export interface BookingSlot {
  /** As shown, e.g. "9:00 AM". */
  label: string;
  /** Already taken — shown, not selectable. */
  taken?: boolean;
}

export interface Booking {
  day: Date;
  slot: string;
}

type BookingCardStatus = "idle" | "booking" | "booked";

interface BookingCardContextValue {
  day: Date | null;
  slot: string | null;
  status: BookingCardStatus;
  setDay: (d: Date) => void;
  setSlot: (s: string) => void;
  submit: () => Promise<void>;
  reset: () => void;
}

const BookingCardContext = createContext<BookingCardContextValue | null>(null);

function useBookingCard(part: string) {
  const ctx = useContext(BookingCardContext);
  if (!ctx) throw new Error(`<BookingCard.${part}> must be inside <BookingCard>`);
  return ctx;
}

export interface BookingCardProps {
  /**
   * Called when the person confirms. Return a promise to hold the button in
   * its busy state until the booking is really made.
   */
  onBook?: (booking: Booking) => void | Promise<void>;
  children: React.ReactNode;
  className?: string;
}

/**
 * Holds the chosen day and slot and runs the confirm. Put `BookingCard.Days`,
 * `BookingCard.Slots`, `BookingCard.Submit` and `BookingCard.Confirmation`
 * inside it in any layout you like.
 *
 * The card is surface-neutral: it draws no background of its own, so it can
 * sit inside any panel — a glass slab, a plain bordered card, a modal. The
 * confirmation covers exactly this element, so make the BookingCard the padded
 * panel itself (heading included) rather than a child of it — otherwise the
 * cover stops short of the panel's edges. Its corners follow the panel's.
 */
export function BookingCard({ onBook, children, className }: BookingCardProps) {
  const [day, setDayState] = useState<Date | null>(null);
  const [slot, setSlot] = useState<string | null>(null);
  const [status, setStatus] = useState<BookingCardStatus>("idle");

  const setDay = (d: Date) => {
    setDayState(d);
    setSlot(null); // a new day means new availability
  };

  const submit = async () => {
    if (!day || !slot || status !== "idle") return;
    setStatus("booking");
    try {
      await onBook?.({ day, slot });
      setStatus("booked");
    } catch {
      setStatus("idle");
    }
  };

  const reset = () => {
    setDayState(null);
    setSlot(null);
    setStatus("idle");
  };

  return (
    <BookingCardContext.Provider value={{ day, slot, status, setDay, setSlot, submit, reset }}>
      <div className={cn("relative rounded-[inherit]", className)}>{children}</div>
    </BookingCardContext.Provider>
  );
}

const sameDay = (a: Date, b: Date) =>
  a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();

const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "short" });
const MONTH = new Intl.DateTimeFormat("en-US", { month: "long" });
const LONG_DATE = new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric" });

export interface BookingCardDaysProps {
  /**
   * Days on offer, in order, paged `count` at a time. Defaults to every day
   * from today up to `horizon` days out.
   */
  days?: Date[];
  /** Days shown per page. */
  count?: number;
  /** How far ahead the default days run, in days from today. */
  horizon?: number;
  /** Days with nothing free — shown, not selectable. */
  unavailable?: (day: Date) => boolean;
  className?: string;
}

const daysFromToday = (length: number) => {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  return Array.from({ length }, (_, i) => {
    const d = new Date(today);
    d.setDate(today.getDate() + i);
    return d;
  });
};

/** False on the server and during hydration, true once the client has taken over. */
const subscribeToNothing = () => () => {};
const useIsMounted = () =>
  useSyncExternalStore(
    subscribeToNothing,
    () => true,
    () => false,
  );

/** "September", or "September – October" when the page straddles a month. */
const monthRange = (first?: Date, last?: Date) => {
  if (!first) return "";
  const a = MONTH.format(first);
  const b = last ? MONTH.format(last) : a;
  return a === b ? a : `${a} – ${b}`;
};

function BookingCardDays({ days: daysProp, count = 7, horizon = 90, unavailable, className }: BookingCardDaysProps) {
  const { day, setDay } = useBookingCard("Days");
  // Built on the client only — a server render has no idea what "today" is.
  const mounted = useIsMounted();
  const defaultDays = useMemo(
    () => (mounted ? daysFromToday(horizon) : []),
    [mounted, horizon],
  );
  const days = daysProp ?? defaultDays;

  // The list starts today (or at the first day handed in), so page 0 is the
  // earliest anyone can go — there is no way to page back into the past.
  const [page, setPage] = useState(0);
  const pageCount = Math.max(1, Math.ceil(days.length / count));
  const visible = days.slice(page * count, page * count + count);
  const atStart = page === 0;
  const atEnd = page >= pageCount - 1;

  return (
    <div className={className}>
      <div className="flex items-center justify-between gap-2">
        <p className="text-sm font-semibold">{monthRange(visible[0], visible[visible.length - 1])}</p>
        <div className="flex gap-1">
          {[
            { label: "Previous days", Icon: ChevronLeft, disabled: atStart, step: -1 },
            { label: "Next days", Icon: ChevronRight, disabled: atEnd, step: 1 },
          ].map(({ label, Icon, disabled, step }) => (
            <button
              key={label}
              type="button"
              aria-label={label}
              disabled={disabled}
              // Clamped, not just disabled: rapid clicks queue up before the
              // disabled state re-renders and would otherwise run off the end.
              onClick={() => setPage((p) => Math.min(Math.max(p + step, 0), pageCount - 1))}
              className={cn(
                "grid size-7 place-items-center rounded-full transition-colors",
                "hover:bg-foreground/5 disabled:cursor-not-allowed disabled:opacity-30 disabled:hover:bg-transparent",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary",
              )}
            >
              <Icon className="size-4" aria-hidden />
            </button>
          ))}
        </div>
      </div>
      <div role="radiogroup" aria-label="Day" className="mt-3 grid grid-cols-7 gap-1.5">
        {visible.map((d) => {
          const selected = day !== null && sameDay(d, day);
          const off = unavailable?.(d) ?? false;
          return (
            <button
              key={d.toISOString()}
              type="button"
              role="radio"
              aria-checked={selected}
              aria-label={LONG_DATE.format(d)}
              disabled={off}
              onClick={() => setDay(d)}
              className={cn(
                "flex flex-col items-center gap-1 rounded-2xl py-2 text-xs transition-colors",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary",
                selected
                  ? "bg-primary text-primary-foreground"
                  : off
                    ? "text-foreground/30 line-through"
                    : "hover:bg-foreground/5",
              )}
            >
              <span className={cn("text-[10px] uppercase", selected ? "opacity-70" : "text-foreground/50")}>
                {WEEKDAY.format(d).slice(0, 3)}
              </span>
              <span className="text-sm font-semibold tabular-nums">{d.getDate()}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

export interface BookingCardSlotsProps {
  /** Group title, e.g. "Morning". */
  label: string;
  slots: BookingSlot[];
  className?: string;
}

function BookingCardSlots({ label, slots, className }: BookingCardSlotsProps) {
  const { day, slot, setSlot } = useBookingCard("Slots");
  return (
    <div className={className}>
      <p className="text-xs text-foreground/50">{label}</p>
      <div role="radiogroup" aria-label={`${label} times`} className="mt-2 flex flex-wrap gap-2">
        {slots.map((s) => {
          const selected = slot === s.label;
          return (
            <button
              key={s.label}
              type="button"
              role="radio"
              aria-checked={selected}
              disabled={s.taken || day === null}
              onClick={() => setSlot(s.label)}
              className={cn(
                "h-9 rounded-full border px-3.5 text-xs font-medium tabular-nums transition-colors",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary",
                selected
                  ? "border-transparent bg-primary text-primary-foreground"
                  : s.taken
                    ? "border-transparent text-foreground/30 line-through"
                    : "border-foreground/10 bg-foreground/[0.03] hover:bg-foreground/[0.06] disabled:opacity-50",
              )}
            >
              {s.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}

export interface BookingCardSubmitProps {
  children?: React.ReactNode;
  className?: string;
}

function BookingCardSubmit({ children = "Book now", className }: BookingCardSubmitProps) {
  const { day, slot, status, submit } = useBookingCard("Submit");
  const ready = day !== null && slot !== null;
  const busy = status === "booking";
  return (
    <button
      type="button"
      disabled={!ready || busy}
      aria-busy={busy}
      onClick={submit}
      className={cn(
        "inline-flex h-11 w-full items-center justify-center gap-2 rounded-full bg-primary px-5 text-sm font-medium text-primary-foreground transition-[background-color,transform] hover:bg-primary/90 active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-40 disabled:active:scale-100",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        className,
      )}
    >
      {busy ? (
        <>
          <span className="size-4 animate-spin rounded-full border-2 border-primary-foreground/40 border-t-primary-foreground motion-reduce:animate-none" />
          Booking
        </>
      ) : ready && day ? (
        `${children}, ${WEEKDAY.format(day)} ${day.getDate()} at ${slot}`
      ) : (
        children
      )}
    </button>
  );
}

export interface BookingCardConfirmationProps {
  /** Who the appointment is with, e.g. "Dr. Priya Nair". */
  withName: string;
  /** Where, e.g. "Riverside Heart & Medical Group". */
  place?: string;
  className?: string;
}

// The cover fades in and out over 0.25s. Inside it the ring draws (0.5s), the
// check follows (0.35s from 0.45s), the details rise 12px (0.35s from 0.7s)
// and the actions fade in (0.3s from 1s) — all ease-out. The strokes draw the
// way Framer Motion's `pathLength` does: `pathLength="1"` on the shape and
// a dash array growing from "0 1" to "1 1".
const CONFIRMATION_CSS = `
.booking-card-confirmation { transition: opacity 0.25s cubic-bezier(0, 0, 0.58, 1); }
.booking-card-confirmation[data-state="closed"] { opacity: 0; }
@starting-style {
  .booking-card-confirmation[data-state="open"] { opacity: 0; }
}
@keyframes booking-card-draw {
  from { stroke-dasharray: 0px 1px; }
  to { stroke-dasharray: 1px 1px; }
}
@keyframes booking-card-rise { from { opacity: 0; translate: 0 12px; } }
@keyframes booking-card-fade { from { opacity: 0; } }
.booking-card-ring { animation: booking-card-draw 0.5s cubic-bezier(0, 0, 0.58, 1) both; }
.booking-card-check { animation: booking-card-draw 0.35s cubic-bezier(0, 0, 0.58, 1) 0.45s both; }
.booking-card-details { animation: booking-card-rise 0.35s cubic-bezier(0, 0, 0.58, 1) 0.7s backwards; }
.booking-card-actions { animation: booking-card-fade 0.3s cubic-bezier(0, 0, 0.58, 1) 1s backwards; }
`;

/**
 * Covers the card once a booking is made: the check draws itself, then the
 * details rise in. "Book another" clears it.
 */
function BookingCardConfirmation({ withName, place, className }: BookingCardConfirmationProps) {
  const { day, slot, status, reset } = useBookingCard("Confirmation");
  const open = status === "booked" && day !== null && slot !== null;

  // "Book another" clears the day and slot straight away, but the cover is
  // still fading out: it keeps showing the booking it opened with.
  const [booked, setBooked] = useState<Booking | null>(null);
  if (open && (booked?.day !== day || booked?.slot !== slot)) setBooked({ day, slot });
  const [mounted, setMounted] = useState(open);
  if (open && !mounted) setMounted(true);

  useEffect(() => {
    if (open || !mounted) return;
    // Backstop for when no transitionend arrives (e.g. a hidden tab).
    const timer = setTimeout(() => setMounted(false), 300);
    return () => clearTimeout(timer);
  }, [open, mounted]);

  const shown = open ? { day, slot } : booked;

  return (
    <>
      {mounted && shown && (
        <div
          role="status"
          data-state={open ? "open" : "closed"}
          onTransitionEnd={(e) => {
            if (e.target === e.currentTarget && e.propertyName === "opacity" && !open) {
              setMounted(false);
            }
          }}
          className={cn(
            "booking-card-confirmation absolute inset-0 z-10 flex flex-col items-center justify-center gap-4 rounded-[inherit] bg-card/85 p-6 text-center backdrop-blur-xl",
            className,
